41	// Strip every leading and trailing `c` from `s` (mirrors Python str.strip(c)).
42	std::string strip_char(std::string s, char c) {
43	  size_t b = 0, e = s.size();
44	  while (b < e && s[b] == c) ++b;
45	  while (e > b && s[e - 1] == c) --e;
46	  return s.substr(b, e - b);
47	}
